intmain(){
intloopCount=5;//eachprocesswillgetitsownloopCount
cout<<"Iamstillonlyoneprocess."<<endl;
pid_treturnedValue=fork();
if(returnedValue<0){
//stillonlyoneprocess
perror("errorforking");//reporttheerror
return-1;
}elseif(returnedValue==0){
//thismustbethechildprocess
while(loopCount>0){
cout<<"Iamthechildprocess."<<endl;
loopCount--;//decrementchild’scounteronly
sleep(1);//waitasecondbeforerepeating
}
}else{
//thismustbetheparentprocess
while(loopCount>0){
cout<<"Iamtheparentprocess;mychild’sIDis"
<<returnedValue<<"."<<endl;
loopCount--;//decrementparent’scounteronly
sleep(1);
}
}
return0;
}
